CREATE DATABASE IF NOT EXISTS sistem_pendataan_rt CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE sistem_pendataan_rt;
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY,nama VARCHAR(100) NOT NULL,username VARCHAR(50) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('Admin','User') NOT NULL DEFAULT 'User',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE warga (id INT AUTO_INCREMENT PRIMARY KEY,nik VARCHAR(16) NOT NULL UNIQUE,nama VARCHAR(100) NOT NULL,jk ENUM('L','P') NOT NULL,ttl VARCHAR(100) NOT NULL,alamat VARCHAR(255) NOT NULL,pekerjaan VARCHAR(100) NOT NULL,kk VARCHAR(16) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE mutasi (id INT AUTO_INCREMENT PRIMARY KEY,warga_id INT NOT NULL,tanggal DATE NOT NULL,jenis ENUM('Pindah Masuk','Pindah Keluar','Kelahiran','Kematian') NOT NULL,keterangan TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(warga_id) REFERENCES warga(id) ON DELETE CASCADE);
CREATE TABLE surat (id INT AUTO_INCREMENT PRIMARY KEY,warga_id INT NOT NULL,tanggal DATE NOT NULL,jenis VARCHAR(150) NOT NULL,status ENUM('Menunggu','Disetujui','Ditolak') DEFAULT 'Menunggu',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(warga_id) REFERENCES warga(id) ON DELETE CASCADE);
